    public boolean preProcess()
    {
		if (classIdGet(request) == classNum(TFMRequestBasicElement))
        {
            return true;
        }
        // Get the dimension setup for the item
        unplannedMoveRequest = request;
        mobInventDimSetup   = TFMInventDimSetup::Construct(unplannedMoveRequest.parmInventTable());
        return true;
    }

