public Map unplannedMoveRegistrationCollectors()
{
    Map returnMap;
    Map replaceLabels = new Map(Types::String, Types::String);
    Map validationDocs = new Map(Types::String, Types::String);
    SysDictType dictType;
    int add = 10;
    InventDimParm parm, InventDimParm;
    InventDimParm.initFromInventDim(unplannedMoveRequest.parmInventDim());
    parm =  InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(unplannedMoveRequest.parmInventTable()));
    parm = InventDimParm::xorParms(inventDimParm,parm);
    parm.InventSiteIdFlag = NoYes::No;
    parm.InventLocationIdFlag = NoYes::No;

    #if.isAX6
    parm.WMSPalletIdFlag = mobInventDimSetup.registerWMSPallet();

    #endif

    //Ensure, that if item is not serialnumber controlled, ask for Qty instead
    parm.InventSerialIdFlag = NoYes::Yes;
    replaceLabels.insert(extendedTypeStr(WMSLocationId),"@SYS50352");
    returnMap = MobInventDimHelper::GetInventDimCollectors(add, mobInventDimSetup,parm,replaceLabels, validationDocs);
    add = returnMap.elements() *10 + add;

    if (mobInventDimSetup.registerWMSLocation() && !mobInventDimSetup.registerWMSPallet())
    {
        // Add the step to register the TO location
        add+=10;
        dictType = new SysDictType(extendedTypeNum(WMSLocationId));
        returnMap.insert(MobConstants::ToLocation(),TFMRegistrationCollectorText::TextStepMap(false,add,'To' + extendedTypeStr(WMSLocationId),"@MobileWMS:MEL44","@SYS50351","@MobileWMS:MEL45",dictType.stringLen()));
    }
    else if (mobInventDimSetup.registerWMSPallet())
    {
        // Add the step to register the TO location
        add+=10;
        dictType = new SysDictType(extendedTypeNum(WHSLicensePlateId));
        returnMap.insert(MobConstants::ToLocation(),TFMRegistrationCollectorText::TextStepMap(false,add,'To' + new DictField(tablenum(WHSLicensePlate), fieldnum(WHSLicensePlate, LicensePlateId)).name(),new DictField(tablenum(WHSLicensePlate), fieldnum(WHSLicensePlate, LicensePlateId)).Label() + ' ('+"@MobileWMS:MEL45"+')',new DictField(tablenum(WHSLicensePlate), fieldnum(WHSLicensePlate, LicensePlateId)).Label(),"@MobileWMS:MEL45",dictType.stringLen()));
    }

    return returnMap;
}

[TFMPostMethod(tableStr(inventJournalTable))]
public void postUnplannedMove()
{
    InventDim       inventDimIssue;
    InventDim       inventDimReceipt;
    Qty             qty;
    ItemId          itemId = unplannedMoveRequest.parmItemId();

    inventDimIssue.data(unplannedMoveRequest.parmInventDim());
    inventDimReceipt.data(unplannedMoveRequest.parmInventDim());

    inventDimIssue = unplannedMoveRequest.createFromInventDim(inventDimIssue);
    inventDimReceipt = unplannedMoveRequest.createToInventDim(inventDimReceipt);
    qty = unplannedMoveRequest.parmQuantity();


    inventJournalTable = MobPostHelper::inventJournalTransfer(qty,itemId,inventDimIssue, inventDimReceipt);
    resultStr =  "@MobileWMS:MEL47";


}
